// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // fuzzed parameter: the _tos array (must be at least one dimension allowing empty array)
    function testFuzz_property(address[] memory tos) public {
        // general admissible domain: any array of addresses (including empty) is allowed by fuzzer
        // We call transfer with some arbitrary 'from' and 'caddress' (use address(1) for from, and a benign callee)
        address from = address(1);
        // We deploy a recorder contract that will accept the calls; it always returns true so it doesn't cause revert
        Recorder r = new Recorder();

        bool ok;
        // call through try/catch to capture whether it reverts or not
        try c.transfer(from, address(r), tos, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // ASSERTION: The reference contract requires _tos to be non-empty and thus must revert when tos.length == 0.
        // Therefore, for ALL inputs, if tos.length == 0 then transfer must revert (ok == false).
        if (tos.length == 0) {
            assertTrue(!ok);
        } else {
            // when tos is non-empty, both reference and mutant can succeed; we don't assert on that case
            assertTrue(true);
        }
    }
}

// Minimal benign recorder: matches the selector transferFrom(address,address,uint256)
contract Recorder {
    // record calls count and last values (not strictly needed here but useful)
    uint public calls;
    address public lastFrom;
    address public lastTo;
    uint public lastV;

    // function signature that C encodes: transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        calls += 1;
        lastFrom = from;
        lastTo = to;
        lastV = v;
        return true;
    }
}
